      setLog([]);
      setRound(value => value + 1);
    };

    const handleParentClick = event => record("parent", event);
    const handleChildClick = event => {
      record("child", event);
      setBound(false);
    };

    parent.addEventListener("pointerdown", startRound, true);
    parent.addEventListener("click", handleParentClick);
    child.addEventListener("click", handleChildClick, { once: true });

    return () => {
      parent.removeEventListener("pointerdown", startRound, true);
      parent.removeEventListener("click", handleParentClick);
