const { useEffect, useRef, useState } = React;

const PHASES = {
  1: { label: "捕获", color: "blue" },
  2: { label: "目标", color: "orange" },
  3: { label: "冒泡", color: "green" },
};
const STEP_MS = 240;

const OptionChip = ({ children }) => (
  <code className="rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-tiny text-ink-2">
    {children}
  </code>
);

const Component = () => {
  const parentRef = useRef(null);
  const childRef = useRef(null);
  const [round, setRound] = useState(0);
  const [log, setLog] = useState([]);
  const [bound, setBound] = useState(true);
  const [binding, setBinding] = useState(0);
  const rebind = () => {
    setBound(true);
    setBinding(value => value + 1);
  };

  useEffect(() => {
    const parent = parentRef.current;
    const child = childRef.current;
    const record = (name, event) => {
      // eventPhase 只在派发期间有效，必须同步读出，不能放进 setState 的更新函数
      const phase = event.eventPhase;
      setLog(entries => [...entries, { name, phase }]);
    };
    // 每次按下开始新一轮记录，只展示这一次点击触发的处理器
    const startRound = () => {
      setLog([]);
      setRound(value => value + 1);
    };

    const controller = new AbortController();
    const { signal } = controller;
    const handleParentClick = event => {
      record("parent", event);
      controller.abort();
      setBound(false);
    };
    const handleChildClick = event => record("child", event);

    parent.addEventListener("pointerdown", startRound, true);
    parent.addEventListener("click", handleParentClick, { signal });
    child.addEventListener("click", handleChildClick);

    return () => {
      controller.abort();
      parent.removeEventListener("pointerdown", startRound, true);
      parent.removeEventListener("click", handleParentClick);
      child.removeEventListener("click", handleChildClick);
    };
  }, [binding]);

  const flash = name => {
    const index = log.findIndex(entry => entry.name === name);
    if (index < 0) return null;
    return (
      <span
        key={`${round}-${name}`}
        className="cb-flash pointer-events-none absolute inset-0 rounded-[inherit]"
        style={{ animationDelay: `${index * STEP_MS}ms` }}
      />
    );
  };

  return (
    <div className="@container flex flex-col gap-3">
      <style>{`
        @scope {
          .cb-flash {
            background: var(--tau-accent-soft);
            box-shadow: inset 0 0 0 2px var(--tau-accent);
            animation: cb-evt-flash 720ms var(--tau-ease-out) both;
          }
          .cb-row { animation: cb-evt-row 320ms var(--tau-ease-out) both; }
          @media (prefers-reduced-motion: reduce) {
            .cb-flash, .cb-row { animation-duration: 1ms; }
          }
        }
        @keyframes cb-evt-flash {
          0% { opacity: 0; }
          18% { opacity: 1; }
          100% { opacity: 0; }
        }
        @keyframes cb-evt-row {
          from { opacity: 0; transform: translateY(4px); }
          to { opacity: 1; transform: none; }
        }
      `}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="min-w-0">
          <div
            ref={parentRef}
            className="relative flex h-[208px] cursor-pointer select-none flex-col rounded-tau-md border border-line-1 bg-surface p-3"
          >
            {flash("parent")}
            <div className="pointer-events-none flex items-center gap-2">
              <span className="font-tau-mono text-tau-meta text-ink-2">parent</span>
              <OptionChip>{"{ signal }"}</OptionChip>
              {!bound && (
                <ui.Tag color="gray" showDot={false}>
                  已移除
                </ui.Tag>
              )}
            </div>
            <div className="flex flex-1 items-center justify-center">
              <div
                ref={childRef}
                className="relative flex h-[96px] w-[58%] flex-col items-center justify-center gap-1.5 rounded-tau-sm border border-accent/25 bg-accent-soft"
              >
                {flash("child")}
                <div className="pointer-events-none flex flex-col items-center gap-1.5">
                  <span className="font-tau-mono text-tau-meta text-accent-text">child</span>
                </div>
              </div>
            </div>
          </div>
        </div>
        <div className="flex flex-col gap-2 rounded-tau-md border border-line-1 p-3">
          <span className="text-tau-sm text-ink-3">执行顺序</span>
          {log.length ? (
            <ol className="flex flex-col gap-2">
              {log.map((entry, index) => (
                <li
                  key={`${round}-${index}`}
                  className="cb-row flex items-center gap-2"
                  style={{ animationDelay: `${index * STEP_MS}ms` }}
                >
                  <span className="grid size-5 shrink-0 place-items-center rounded-full bg-hover font-tau-mono text-tau-tiny text-ink-2">
                    {index + 1}
                  </span>
                  <span className="min-w-0 font-tau-mono text-tau-meta text-ink-1">{entry.name}</span>
                  <ui.Tag color={PHASES[entry.phase].color} className="ml-auto shrink-0">
                    {PHASES[entry.phase].label}
                  </ui.Tag>
                </li>
              ))}
            </ol>
          ) : (
            <p className="text-tau-meta text-ink-3">点击 parent 或 child</p>
          )}
          <div className="mt-auto pt-1">
            <ui.Button variant="ghost" size="sm" icon={icons.RotateCcw} onClick={rebind}>
              重新绑定
            </ui.Button>
          </div>
        </div>
      </div>
    </div>
  );
};
